    "reaction_strength": "↘",
    "tension_stars": 4,
    "forbidden_elements": ["不要轻松甜宠", "不要大团圆结局", "不要穿越", "不要超自然元素"],
    "x_axis_display": "两个相爱的人因政治任务被迫伪装成陌生人，在组织的严密监视下重燃旧情",
    "y_axis_combination_effect": "商战权谋提供政治高压背景，先婚后爱强化情感张力，两人在体制压迫下的禁忌之恋",
    "reaction_formula": "政治任务的死敌伪装 + 青梅竹马的旧情复燃 = 体制高压下的虐心禁忌之恋",
    "platform_fit": ["晋江", "长佩", "豆瓣阅读"]
  },
  "one_sentence_synopsis": "政治联姻下的青梅竹马在军区大院新房重逢，两人被迫装作陌生人，在组织监视下重燃旧情，最终走向悲剧结局。"
}", "path": "creative_intent.json"}]}

